import java.util.*;
import java.util.stream.*;

public class Ex08ExclusionFilter {
    public static void main(String[] args) {
        List<String> candidates = new ArrayList<>(List.of(
                "DataSourceAutoConfiguration",
                "WebMvcAutoConfiguration",
                "SecurityAutoConfiguration",
                "JacksonAutoConfiguration"));

        Set<String> excludes = new LinkedHashSet<>(List.of("SecurityAutoConfiguration"));

        List<String> effective = candidates.stream()
                .filter(c -> !excludes.contains(c))
                .collect(Collectors.toList());

        System.out.println("candidates = " + candidates.size());
        System.out.println("excluded   = " + excludes);
        System.out.println("effective  = " + effective);
        System.out.println("count      = " + effective.size());
    }
}
